-- the SELECT ALWAYS runs, regardless:
IF 1 = 2
    PRINT 'This never prints';
    SELECT 'This always runs';

IF @ProductCount > 500
BEGIN
    PRINT 'Large catalog';
    PRINT 'Consider archiving old products';
END
ELSE
BEGIN
    PRINT 'Small catalog';
    PRINT 'No archiving needed yet';
